// Space Complexity: O(1)

class Solution {
    public:
        vector<vector<int> > combinationSum2(vector<int> &num, int target) {
            sort(num.begin(), num.end());
            vector<vector<int> > ans;
            vector<int> v;
            dfs(num, target, 0, v, ans);
            return ans;
        }

    private:
        void dfs(vector<int>& num, int gap, int begin, vector<int>& v,vector<vector<int> > &ans) {
            if (gap == 0) {
                ans.push_back(v);
                return;
            }

            for (size_t i = begin; i < num.size(); i++) {
                if (gap < num[i]) return; // pruning
                if( i > begin && num[i] == num[i - 1]) // skip duplicates
                    continue;
                v.push_back(num[i]);
                dfs(num, gap - num[i], i + 1, v, ans); // each element could be chosen only once
                v.pop_back();
            }
        }
};

kamyu-c-compare-strings-by-frequency-of-:
// Time:  O((m + n)logn), m is the number of queries, n is the number of words
// Space: O(n)

class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        vector<int> words_freq;
        for (const auto& word : words) {
            words_freq.emplace_back(f(word));
        }
        sort(words_freq.begin(), words_freq.end());
        vector<int> result;
        for (const auto& query : queries) {
            const auto& it = upper_bound(words_freq.cbegin(), words_freq.cend(), f(query));
            result.emplace_back(distance(it, words_freq.cend()));
        }
        return result;
    }

private:
    int f(const string& word) {
        const auto& smallest = *min_element(word.cbegin(), word.cend());
        return count(word.cbegin(), word.cend(), smallest);
    }
};

