// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    bool canConstruct(string s, int k) {
        const auto& count = counter(s);
        const auto& odd = accumulate(cbegin(count), cend(count), 0,
                              [](const auto& a, const auto& b) {
                                  return a + b.second % 2;
                          });
        return odd <= k && k <= s.length();
    }

