// Time:  O(26 * n)
// Space: O(26)

// greedy
class Solution {
public:
    string repeatLimitedString(string s, int repeatLimit) {
        vector<int> cnt(26);
        for (const auto& c : s) {
            ++cnt[c - 'a'];
        }
        string result;
        int top1 = 25;
        for (;;) {
            for (; top1 >= 0; --top1) {
                if (cnt[top1]) {
                    break;
                }
            }
            if (top1 == -1) {
                break;
            }
            const int c = min(cnt[top1], repeatLimit - static_cast<int>(!empty(result) && result.back() == 'a' + top1));
            cnt[top1] -= c;
            result.append(c, 'a' + top1);
            int top2 = top1 - 1;
            for (; top2 >= 0; --top2) {
                if (cnt[top2]) {
                    break;
                }
            }
            if (top2 == -1) {
                break;
            }
            --cnt[top2];
            result.push_back('a' + top2);
        }
        return result;
    }
};

kamyu-c-construct-target-array-with-mult:
// Time:  O(log(max(t)) * logn)
// Space: O(n)

class Solution {
public:
    bool isPossible(vector<int>& target) {
        // (1) x + remain = y
        // (2) y + remain = total
        // (1) - (2) => x - y = y - total
        //           => x = 2*y - total
        auto total = accumulate(cbegin(target), cend(target), 0ll);
        priority_queue<int> max_heap(cbegin(target), cend(target));
        while (total != target.size()) {
            const auto y = max_heap.top(); max_heap.pop();
            const auto& remain = total - y;
            auto x = y - remain;
            if (x <= 0) {
                return false;
            }
            if (x > remain) {  // for case [1, 1000000000]
                x = x % remain + remain;
            }
            max_heap.emplace(x);
            total = x + remain;
        }
        return true;
    }
};

kamyu-c-construct-the-lexicographically-:
// Time:  O(n!)
// Space: O(n)

class Solution {
public:
    vector<int> constructDistancedSequence(int n) {
        vector<int> result(2 * n - 1);
        vector<bool> lookup(n + 1);
        backtracking(n, 0, &lookup, &result);
        return result;
    }

private:
    bool backtracking(int n, int i, vector<bool> *lookup, vector<int> *result) {
        if (i == size(*result)) {
            return true;
        }
        if ((*result)[i]) {
            return backtracking(n, i + 1, lookup, result);
        }
        for (int x = n; x >= 1; --x) {
            int j = (x == 1) ? i : i + x;
            if ((*lookup)[x] || j >= size(*result) || (*result)[j]) {
                continue;
            }
            (*result)[i] = (*result)[j] = x, (*lookup)[x] = true;
            if (backtracking(n, i + 1, lookup, result)) {
                return true;
            }
            (*result)[i] = (*result)[j] = 0, (*lookup)[x] = false;

        }
        return false;
    }
};

