        }
        int result = 0;
        for (const auto& x : dig) {
            if (!lookup.count(x[0] * n + x[1])) {
                continue;
            }
            result += static_cast<int>(--cnt[lookup[x[0] * n + x[1]]] == 0);
        }
        return result;
    }
};

