// Time:  O(h * h) = O((logn)^2)
// Space: O(1)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int countNodes(TreeNode* root) {
        int count = 0, h = height(root);
        while (root) {
            if (height(root->right) == h - 1) {
                count += 1 << h;
                root = root->right;
            } else {
                count += 1 << (h - 1);
                root = root->left;
            }
            --h;
        }
        return count;
    }

private:
    int height(TreeNode *root) {
        int h = -1;
        while (root) {
            ++h;
            root = root->left;
        }
        return h;
    }
};

// Time:  O(h * logn) = O((logn)^2)
// Space: O(1)
class Solution2 {
public:
    int countNodes(TreeNode* root) {
        if (root == nullptr) {
            return 0;
        }

        TreeNode *node = root;
        int level = 0;
        while (node->left != nullptr) {
            node = node->left;
            ++level;
        }
        int left = pow(2, level), right = pow(2, level + 1) - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (!check(root, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;  // find the the first node from right exists
    }

private:
    // Check if the nth node exist.
    bool check(TreeNode *root, int n) {
        //       1(1)
        //     /      \
        //   2(0)     3(1)   ↑
        //  /  \      /      d
        // 4(0) 5(1) 6(0)    ↓
        int base = 1;
        while (base <= n) {
            base <<= 1;
        }
        base >>= 2;  // base = 2^d
        TreeNode *node = root;
        while (base) {
            if ((n & base) == 0) {
                node = node->left;
            } else {
                node = node->right;
            }
            base >>= 1;
        }
        return node != nullptr;
    }
};

kamyu-c-count-connected-components-in-lc:
// Time:  O(n + tlogt), t = threshold
// Space: O(t)

// union find, number theory
class UnionFind {
public:
    UnionFind(int n)
        : set_(n)
        , rank_(n) {
        iota(set_.begin(), set_.end(), 0);
    }

    int find_set(int x) {
        if (set_[x] != x) {
            set_[x] = find_set(set_[x]);  // Path compression.
        }
        return set_[x];
    }

    bool union_set(int x, int y) {
        x = find_set(x), y = find_set(y);
        if (x == y) {
            return false;
        }
        if (rank_[x] > rank_[y]) {
            swap(x, y);
        }
        set_[x] = y;  // Union by rank.
        if (rank_[x] == rank_[y]) {
            ++rank_[y];
        }
        return true;
    }

private:
    vector<int> set_;
    vector<int> rank_;
};

class Solution {
public:
    int countComponents(vector<int>& nums, int threshold) {
        UnionFind uf(threshold);
        vector<int> lookup(threshold, -1);
        int result = size(nums);
        for (const auto& x : nums) {
            if (x - 1 >= threshold) {
                continue;
            }
            for (int i = x; i <= threshold; i += x) {
                if (lookup[i - 1] == -1) {
                    lookup[i - 1] = x - 1;
                    continue;
                }
                if (uf.union_set(lookup[i - 1], x - 1)) {
                    --result;
                }
                if (i == x) {
                    break;
                }
            }
        }
        return result;
    }
};

// Time:  O(n + tlogt), t = threshold
// Space: O(t)
// union find, number theory
class Solution2 {
public:
    int countComponents(vector<int>& nums, int threshold) {
        UnionFind uf(threshold);
        for (const auto& x : nums) {
            if (x - 1 >= threshold) {
                continue;
            }
            for (int i = x + x; i <= threshold; i += x) {
                uf.union_set(i - 1, x - 1);
            }
        }
        int result = 0;
        for (const auto& x : nums) {
            if (x - 1 >= threshold || uf.find_set(x - 1) == x - 1) {
                ++result;
            }
        }
        return result;
    }
};

