        int64_t base = pow(9, size(s));
        int64_t result = (base - 9) / (9 - 1);
        base /= 9;
        for (const auto& x : s) {
            if (x == '0') {
                break;
            }
            result += ((x - '0') - 1) * base;
            base /= 9;
        }
        if (base == 0) {
            ++result;
        }
        return result;
    }
};

