kamyu-c-count-k-reducible-numbers-less-t:
// Time:  O(n^2)
// Space: O(n)

// dp
vector<int> cnt = {0, 0};
class Solution {
public:
    int countKReducibleNumbers(string s, int k) {
        static const int MOD = 1e9 + 7;

        while (size(s) - 1 >= size(cnt)) {  // cached
            cnt.emplace_back(cnt[__builtin_popcount(size(cnt))] + 1);
        }
        vector<int> dp(size(s));
        for (int i = 0, curr = 0; i < size(s); ++i) {
            for (int j = i - 1; j >= 0; --j) {
                dp[j + 1] = (dp[j + 1] + dp[j]) % MOD;
            }
            if (s[i] != '1') {
                continue;
            }
            dp[curr] = (dp[curr] + 1) % MOD;
            ++curr;
        }
        int result = 0;
        for (int i = 1; i < size(s); ++i) {
            if (cnt[i] < k) {
                result = (result + dp[i]) % MOD;
            }
        }
        return result;
    }
};

// Time:  O(n^2)
// Space: O(n)
// dp, combinatorics
// vector<int> cnt = {0, 0};
class Solution2 {
public:
    int countKReducibleNumbers(string s, int k) {
        static const int MOD = 1e9 + 7;
        vector<int> fact = {1, 1};
        vector<int> inv = {1, 1};
        vector<int> inv_fact = {1, 1};
        const auto& nCr = [&](int n, int k) {
            while (size(inv) <= n) {  // lazy initialization
                fact.emplace_back((static_cast<int64_t>(fact.back()) * size(inv)) % MOD);
                inv.emplace_back((static_cast<int64_t>(inv[MOD % size(inv)]) * (MOD - MOD / size(inv))) % MOD);  // https://cp-algorithms.com/algebra/module-inverse.html
                inv_fact.emplace_back((static_cast<int64_t>(inv_fact.back()) * inv.back()) % MOD);
            }
            return (((static_cast<int64_t>(fact[n]) * inv_fact[n - k]) % MOD) * inv_fact[k]) % MOD;
        };

        while (size(s) - 1 >= size(cnt)) {  // cached
            cnt.emplace_back(cnt[__builtin_popcount(size(cnt))] + 1);
        }
        int result = 0;
        for (int i = 0, curr = 0; i < size(s); ++i) {
            if (s[i] != '1') {
                continue;
            }
            for (int c = 0; c <= size(s) - (i + 1); ++c) {
                if (cnt[curr + c] < k) {
                    result = (result + nCr(size(s) - (i + 1), c)) % MOD;
                }
            }
            ++curr;
        }
        return (((result - 1) % MOD) + MOD) % MOD;
    }
};

kamyu-c-count-k-subsequences-of-a-string:
// Time:  O(n)
// Space: O(1)

// greedy, quick select, combinatorics
class Solution {
public:
    int countKSubsequencesWithMaxBeauty(string s, int k) {
        unordered_map<int, int> cnt;
        for (const auto& c : s) {
            ++cnt[c];
        }
        if (size(cnt) < k) {
            return 0;
        }
        vector<int> freqs;
        freqs.reserve(26);
        for (const auto& [_, v] : cnt) {
            freqs.emplace_back(v);
        }
        nth_element(begin(freqs), begin(freqs) + (k - 1), end(freqs), greater<int>());
        int result = 1;
        for (int i = 0; i < k; ++i) {
            result = mulmod(result, freqs[i]);
        }
        const int n = count(cbegin(freqs), cend(freqs), freqs[k - 1]);
        const int r = count(cbegin(freqs), cbegin(freqs) + k, freqs[k - 1]);
        return mulmod(result, nCr(n, r));
    }

private:
    int nCr(int n, int k) {
        while (size(inv_) <= n) {  // lazy initialization
            fact_.emplace_back(mulmod(fact_.back(), size(inv_)));
            inv_.emplace_back(mulmod(inv_[MOD % size(inv_)], MOD - MOD / size(inv_)));  // https://cp-algorithms.com/algebra/module-inverse.html
            inv_fact_.emplace_back(mulmod(inv_fact_.back(), inv_.back()));
        }
        return mulmod(mulmod(fact_[n], inv_fact_[n - k]), inv_fact_[k]);
    }

    uint32_t addmod(uint32_t a, uint32_t b) {  // avoid overflow
        a %= MOD, b %= MOD;
        if (MOD - a <= b) {
            b -= MOD;  // relied on unsigned integer overflow in order to give the expected results
        }
        return a + b;
    }

    // reference: https://stackoverflow.com/questions/12168348/ways-to-do-modulo-multiplication-with-primitive-types
    uint32_t mulmod(uint32_t a, uint32_t b)  {  // avoid overflow
        a %= MOD, b %= MOD;
        uint32_t result = 0;
        if (a < b) {
            swap(a, b);
        }
        while (b > 0)  { 
            if (b % 2 == 1) {
                result = addmod(result, a);
            }
            a = addmod(a, a);
            b /= 2; 
        } 
        return result; 
    }

    static const uint32_t MOD = 1e9 + 7;
    vector<int> fact_ = {1, 1};
    vector<int> inv_ = {1, 1};
    vector<int> inv_fact_ = {1, 1};
};

kamyu-c-count-k-th-roots-in-a-range-0uxl:
// Time:  O(logr * logk)
// Space: O(1)

// binary search, fast exponentiation
class Solution {
public:
    int countKthRoots(int l, int r, int k) {
        const auto& binary_search_right = [](int left, int right, const auto& check) {
            while (left <= right) {
                const auto& mid = left + (right - left) / 2;
                if (!check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };

        const auto& count = [&](int right) {
            return binary_search_right(0, right, [&](int x) {
                return pow(x, k) <= right;
            }) - 0 + 1;
        };

        return count(r) - count(l - 1);
    }
};

