                if (lookup.count(pair(u, p))) {
                    ++curr;
                }
                result += static_cast<int>(curr >= k);
                for (const auto& v : adj[u]) {
                    if (v == p) {
                        continue;
                    }
                    stk.emplace_back(v, u, curr);
                }
            }
            return result;
        };

        int curr = iter_dfs();
        return iter_dfs2(curr);
    }

private:
