        unordered_map<tuple<int, int, int>, int, TupleHash> lookup_line;
        unordered_map<tuple<int, int, int>, int, TupleHash> lookup_slope_length;
        unordered_map<tuple<int, int, int, int>, int, TupleHash> lookup_line_length;
