                const int c = b * x1 - a * y1;
                result += lookup_slope[tuple(a, b)]++ - lookup_line[tuple(a, b, c)]++;
                const int l = dx * dx + dy * dy;
                same += lookup_slope_length[tuple(a, b, l)]++ - lookup_line_length[tuple(a, b, c, l)]++;
            }
        }
        return result - same / 2;
    }
};

