        for (const auto& edge : edges) {
            ++degree[edge[0]];
            ++degree[edge[1]];
            ++shared[pair(min(edge[0], edge[1]), max(edge[0], edge[1]))];
        }
        vector<int> sorted_degree(degree);
        sort(begin(sorted_degree), end(sorted_degree));
