    int specialTriplets(vector<int>& nums) {
        static const int MOD = 1e9 + 7;

        int result = 0;
        vector<unordered_map<int, int>> dp(2);
        for (const auto& x : nums) {
            if (x % 2 == 0 && dp[1].count(x / 2)) {
                result = (result + dp[1][x / 2]) % MOD;
            }
            if (dp[0].count(2 * x)) {
                dp[1][x] = (dp[1][x] + dp[0][2 * x]) % MOD;
            }
            dp[0][x] = (dp[0][x] + 1) % MOD;
        }
        return result;
    }
};

