        int result = 0;
        for (int i = 0; i < size(grid2); ++i) {
            for (int j = 0; j < size(grid2[0]); ++j) {
                if (grid2[i][j]) {
                    result += dfs(grid1, &grid2, i, j);
                }
            }
        }
