    }

private:
    int dfs(const vector<vector<int>>& grid1,
            vector<vector<int>> *grid2,
            int i, int j) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0},
                                                       {0, -1}, {-1, 0}};
        if (!(0 <= i && i < size(*grid2) &&
              0 <= j && j < size((*grid2)[0]) &&
              (*grid2)[i][j] == 1)) {
            return 1;
        }
        (*grid2)[i][j] = 0;
        int result = grid1[i][j];
        for (const auto& [di, dj] : directions) {
            result &= dfs(grid1, grid2, i + di, j + dj);
        }
        return result;
    }
};

