                }
            }
        }
        return result;
    }
};

// Time:  O(d^2 * n)
// Space: O(d^2)
// dp
class Solution3 {
public:
    long long countSubstrings(string s) {
        int64_t result = 0;
        vector<vector<int>> dp(10, vector<int>(10));
        for (int i = 1; i <= size(s); ++i) {
            vector<vector<int>> new_dp(10, vector<int>(10));
            const int x = s[i - 1] - '0';
            for (int d = 1; d <= 9; ++d) {
                ++new_dp[d][x % d];
                for (int r = 0; r < d; ++r) {
                    new_dp[d][(r * 10 + x) % d] += dp[d][r];
                }
            }
            dp = move(new_dp);
            result += dp[x][0];
        }
        return result;
    }
};

