        const int l = (-1 + sqrt(1 + 4 * size(s))) / 2;  // since c^2 <= n-c, thus c <= (-1+(1+4*n)**0.5)/2
        for (int c = 0; c <= l; ++c) {
            for (int i = 0, left = 1, right = 1; i < size(s); ++i) {
                if (idxs[right] == i) {
                    ++right;
                }
                if (right - left == c + 1) {
                    ++left;
                }
                if (!(right - left == c && ((i - idxs[left - 1]) - c) >= c * c)) {
                    continue;
                }
                result += min(min(idxs[left], i) - idxs[left - 1], ((i - idxs[left - 1]) - c) - c * c + 1);
            }
        }
        return result;
    }
};

